func (q *Queries) UpdateIssue(ctx context.Context, arg UpdateIssueParams) error {
	_, err := q.db.Exec(ctx, updateIssue,
		arg.DeadlineAt,
		arg.LessonID,
		arg.Now,
		arg.ID,
		arg.TutorID,
	)
	return err
}

const visibleIssueSnapshotReferences = `-- name: VisibleIssueSnapshotReferences :many
SELECT issues.id, attachments.width
FROM attachment_references
JOIN issues ON issues.id = attachment_references.ref_id AND issues.erase_pending_since IS NULL
JOIN attachments ON attachments.id = attachment_references.attachment_id AND attachments.state = 'bound'
WHERE attachment_references.attachment_id = $1 AND attachment_references.ref_kind = 'issue_snapshot'
    AND (
        issues.tutor_id = $2::uuid
        OR (
            issues.status = 'active'
            AND EXISTS (
                SELECT 1 FROM submissions
                JOIN relationships ON relationships.id = submissions.relationship_id
                JOIN users AS tutor ON tutor.id = submissions.tutor_id
                WHERE submissions.issue_id = issues.id AND submissions.student_id = $2::uuid
                    AND relationships.state IN ('active', 'provisional', 'ended')
                    AND (tutor.state <> 'deleted' OR tutor.deleted_at > $3::timestamptz)
            )
        )
    )
ORDER BY issues.id
`

type VisibleIssueSnapshotReferencesParams struct {
	AttachmentID      domain.AttachmentID
	Viewer            pgtype.UUID
	TutorDeletedAfter time.Time
}

type VisibleIssueSnapshotReferencesRow struct {
	ID    domain.IssueID
	Width *int32
}

func (q *Queries) VisibleIssueSnapshotReferences(ctx context.Context, arg VisibleIssueSnapshotReferencesParams) ([]VisibleIssueSnapshotReferencesRow, error) {
	rows, err := q.db.Query(ctx, visibleIssueSnapshotReferences, arg.AttachmentID, arg.Viewer, arg.TutorDeletedAfter)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []VisibleIssueSnapshotReferencesRow
	for rows.Next() {
		var i VisibleIssueSnapshotReferencesRow
		if err := rows.Scan(&i.ID, &i.Width); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const withdrawIssue = `-- name: WithdrawIssue :exec
UPDATE issues SET status = 'withdrawn', withdrawn_at = $1::timestamptz, version = version + 1, updated_at = $1::timestamptz WHERE id = $2 AND tutor_id = $3
`

type WithdrawIssueParams struct {
	Now     time.Time
	ID      domain.IssueID
	TutorID domain.UserID
}

func (q *Queries) WithdrawIssue(ctx context.Context, arg WithdrawIssueParams) error {
	_, err := q.db.Exec(ctx, withdrawIssue, arg.Now, arg.ID, arg.TutorID)
	return err
}
